# system registry: each family exposes step(), jac(), init(), kind, d, params
# ----------------------------------------------------------------------------

def _make_lorenz(sigma=10.0, rho=28.0, beta=8.0 / 3.0):
    def f(x):
        return np.array([sigma * (x[1] - x[0]),
                         x[0] * (rho - x[2]) - x[1],
                         x[0] * x[1] - beta * x[3 - 1]])

    def J(x):
        return np.array([[-sigma, sigma, 0.0],
                         [rho - x[2], -1.0, -x[0]],
                         [x[1], x[0], -beta]])

    return f, J


def _make_rossler(a=0.2, b=0.2, c=5.7):
    def f(x):
        return np.array([-x[1] - x[2], x[0] + a * x[1], b + x[2] * (x[0] - c)])

    def J(x):
        return np.array([[0.0, -1.0, -1.0],
                         [1.0, a, 0.0],
                         [x[2], 0.0, x[0] - c]])

    return f, J


def _logistic_step(r):
    def step(x):
        return r * x * (1.0 - x)

    def jac(x):
        return np.array([[r * (1.0 - 2.0 * x[0])]])

    return step, jac


def _coupled_logistic_step(r, c):
    def step(x):
        return np.array([r * x[0] * (1 - x[0]) + c * (x[1] - x[0]),
                         r * x[1] * (1 - x[1]) + c * (x[0] - x[1])])

    def jac(x):
        return np.array([[r * (1 - 2 * x[0]) - c, c],
                         [c, r * (1 - 2 * x[1]) - c]])

    return step, jac


def _hubble_step(u):
    # Hubble map (discrete 2D), parameter u in [0,1]
    def step(x):
        return np.array([x[1],
                         u * x[1] + (1.0 - u) * x[0] ** 2])

    def jac(x):
        return np.array([[0.0, 1.0],
                         [2.0 * (1.0 - u) * x[0], u]])

    return step, jac


def _henon_step(a=1.4, b=0.3):
    def step(x):
        return np.array([1.0 - a * x[0] ** 2 + x[1], b * x[0]])

    def jac(x):
        return np.array([[-2.0 * a * x[0], 1.0],
                         [b, 0.0]])

    return step, jac


def _chain_logistic_step(r, c, n):
    def step(x):
        xp = np.roll(x, 1)
        xm = np.roll(x, -1)
        return r * x * (1 - x) + c * (xp - 2.0 * x + xm)

    def jac(x):
        Jm = np.zeros((n, n))
        for i in range(n):
            Jm[i, i] = r * (1 - 2 * x[i]) - 2.0 * c
            Jm[i, (i + 1) % n] = c
            Jm[i, (i - 1) % n] = c
        return Jm

    return step, jac


class Family:
    """One dynamical system with its own state, dimension and stepping rule."""

    def __init__(self, name, kind, d, step, jac, dt, params, active=None):
        self.name = name
        self.kind = kind          # 'flow' | 'map'
        self.d = d
        self.step = step          # discrete map step (maps) OR unused
        self.jac = jac            # variational right-hand / map Jacobian
        self.dt = dt
        self.params = params
        self.active = d if active is None else active   # genuinely active dims

    # ---- trajectory -------------------------------------------------------
    def integrate(self, x0, n_transient, n_total):
        if self.kind == 'map':
            x = x0.copy()
            for _ in range(n_transient):
                x = self.step(x)
            traj = np.empty((n_total, self.d))
            for i in range(n_total):
                x = self.step(x)
                traj[i] = x
            return traj
        else:
            def f(x):
                return self.jac(x) @ x * 0 + self._rhs(x)
            # rhs stored separately; see _rhs attr
            f = self._rhs
            x = x0.copy()
            for _ in range(n_transient):
                x = rk4(f, x, self.dt)
            traj = np.empty((n_total, self.d))
            for i in range(n_total):
                x = rk4(f, x, self.dt)
                traj[i] = x
            return traj

    # ---- largest Lyapunov exponent ---------------------------------------
    def lyapunov(self, x0, n_transient, n_total):
        d = self.d
        if self.kind == 'map':
            x = x0.copy()
            for _ in range(n_transient):
                x = self.step(x)
            v = np.ones(d) / math.sqrt(d)
            acc = 0.0
            for _ in range(n_total):
                w = self.jac(x) @ v
                nrm = np.linalg.norm(w)
                if nrm < 1e-14:
                    return float('nan')
                v = w / nrm
                acc += math.log(nrm)
                x = self.step(x)
            return acc / n_total
        else:
            def aug(z):
                xx = z[:d]
                Vv = z[d:].reshape(d, d)
                dx = self._rhs(xx)
                dV = self.jac(xx) @ Vv
                return np.concatenate([dx, dV.ravel()])

            x = x0.copy()
            for _ in range(n_transient):
                x = rk4(self._rhs, x, self.dt)
            V = np.eye(d)
            acc = 0.0
            for _ in range(n_total):
                z = np.concatenate([x, V.ravel()])
                z = rk4(aug, z, self.dt)
                x = z[:d]
                V = z[d:].reshape(d, d)
                Q, R = np.linalg.qr(V)
                sgn = np.sign(np.diag(R))
                sgn[sgn == 0] = 1.0
                Q = Q * sgn
                acc += float(np.sum(np.log(np.abs(np.diag(R)) + 1e-300)))
                V = Q
            return acc / (n_total * self.dt)


# ----------------------------------------------------------------------------
# measurements
# ----------------------------------------------------------------------------

def autocorr(ts, maxlag):
    ts = ts - ts.mean()
    v = np.dot(ts, ts)
    if v <= 0:
        return np.zeros(maxlag + 1)
    out = np.empty(maxlag + 1)
    out[0] = 1.0
    for lag in range(1, maxlag + 1):
        out[lag] = np.dot(ts[:-lag], ts[lag:]) / v
    return out


def decorrelation_lag(ts, target=0.5, maxlag=400):
    """Smallest lag whose autocorrelation has fallen to `target`."""
    ac = autocorr(ts, maxlag)
    for lag in range(1, maxlag + 1):
        if ac[lag] <= target:
            return lag, ac[lag]
    return int(np.argmin(np.abs(ac[1:]) ) + 1), ac[-1]


def prediction_accuracy(ts, lag):
    """R^2 of a one-dimensional AR(1) fitted across `lag` steps."""
    a, b = ts[:-lag], ts[lag:]
    am, bm = a.mean(), b.mean()
    den = np.sum((a - am) ** 2)
    if den <= 0:
        return float('nan')
    slope = np.sum((a - am) * (b - bm)) / den
    pred = bm + slope * (a - am)
    ss_res = np.sum((b - pred) ** 2)
    ss_tot = np.sum((b - bm) ** 2)
    if ss_tot <= 0:
        return float('nan')
    return 1.0 - ss_res / ss_tot


def correlation_dimension(ts, m=5, tau=None, n_sub=1200, nr=14):
    """Grassberger-Procaccia slope of log C(r) vs log r over the scaling band."""
    if tau is None:
        tau = max(1, int(np.argmax(autocorr(ts, min(200, len(ts) // 4)) < 1.0 / math.e)))
    n = len(ts) - (m - 1) * tau
    if n < 200:
        return float('nan')
    idx = np.arange(0, n, max(1, n // n_sub))
    emb = np.stack([ts[i * tau:i * tau + n][idx] if False else
                    ts[idx + k * tau] for k in range(m)], axis=1)
    if len(emb) < 100:
        return float('nan')
    # pairwise distances, upper triangle
    D = np.linalg.norm(emb[:, None, :] - emb[None, :, :], axis=-1)
    iu = np.triu_indices(len(emb), k=1)
    dist = D[iu]
    dist = dist[dist > 0]
    if len(dist) < 500:
        return float('nan')
    rmin, rmax = np.percentile(dist, 5), np.percentile(dist, 85)
    if rmax <= rmin:
        return float('nan')
    rs = np.logspace(np.log10(rmin), np.log10(rmax), nr)
    N = len(dist)
    C = np.array([np.sum(dist < r) / N for r in rs])
    ok = (C > 0) & (C < 1)
    if ok.sum() < 6:
        return float('nan')
    # fit the middle band only (scaling region), drop outer 20% of the band
    sel = ok.copy()
    sel_idx = np.where(ok)[0]
    lo = int(0.2 * len(sel_idx))
    hi = int(0.85 * len(sel_idx))
    keep = sel_idx[lo:hi + 1]
    if len(keep) < 4:
        return float('nan')
    slope = np.polyfit(np.log(rs[keep]), np.log(C[keep]), 1)[0]
    return float(slope)


# ----------------------------------------------------------------------------
# candidate law forms
# ----------------------------------------------------------------------------

def fit_forms(z, acc):
    """Fit each candidate form; return params + LOO-CV R^2 (leave-one-family-out)."""
    out = {}
    z = np.asarray(z, float)
    acc = np.asarray(acc, float)

    # --- F_exp : ln acc = b - k z   (closed form) -------------------------
    A = np.vstack([np.ones_like(z), -z]).T
    coef, *_ = np.linalg.lstsq(A, np.log(acc), rcond=None)
    b, k = coef
    pred_all = np.exp(b - k * z)
    out['F_exp'] = dict(k=float(k), b=float(b),
                        r2=float(1 - np.sum((acc - pred_all) ** 2) /
                                 np.sum((acc - acc.mean()) ** 2)))

    # --- F_pow : ln acc = ln a - k ln z -----------------------------------
    A = np.vstack([np.ones_like(z), -np.log(z)]).T
    coef, *_ = np.linalg.lstsq(A, np.log(acc), rcond=None)
    ln_a, kp = coef
    pred_all = np.exp(ln_a) * z ** (-kp)
    out['F_pow'] = dict(k=float(kp), a=float(np.exp(ln_a)),
                        r2=float(1 - np.sum((acc - pred_all) ** 2) /
                                 np.sum((acc - acc.mean()) ** 2)))

    # --- F_log : 1/(1+exp(k(z-z0))) ---------------------------------------
    from scipy.optimize import curve_fit
    def flog(x, k, z0):
        return 1.0 / (1.0 + np.exp(np.clip(k * (x - z0), -40, 40)))
    try:
        p, _ = curve_fit(flog, z, acc, p0=[1.0, np.median(z)], maxfev=20000)
        pred_all = flog(z, *p)
        out['F_log'] = dict(k=float(p[0]), z0=float(p[1]),
                            r2=float(1 - np.sum((acc - pred_all) ** 2) /
                                     np.sum((acc - acc.mean()) ** 2)))
    except Exception:
        out['F_log'] = dict(r2=float('nan'))

    # --- F_hyp : a/(1+k z) -------------------------------------------------
    def fhyp(x, a, k):
        return a / (1.0 + k * x)
    try:
        p, _ = curve_fit(fhyp, z, acc, p0=[1.0, 1.0], maxfev=20000)
        pred_all = fhyp(z, *p)
        out['F_hyp'] = dict(a=float(p[0]), k=float(p[1]),
                            r2=float(1 - np.sum((acc - pred_all) ** 2) /
                                     np.sum((acc - acc.mean()) ** 2)))
    except Exception:
        out['F_hyp'] = dict(r2=float('nan'))

    return out


def loo_family_cv(rows, forms=('F_exp', 'F_pow', 'F_log', 'F_hyp')):
    """Leave-one-FAMILY-out CV R^2 on acc, for each candidate form."""
    fams = sorted(set(r['family'] for r in rows))
    z = np.array([r['z'] for r in rows], float)
    acc = np.array([r['acc'] for r in rows], float)
    fam = np.array([r['family'] for r in rows])
    results = {}
    for form in forms:
        preds, trues = [], []
        ok = True
        for f in fams:
            tr = fam != f
            te = fam == f
            if tr.sum() < 4 or te.sum() == 0:
                continue
            try:
                pr = _predict_form(form, z[tr], acc[tr], z[te])
            except Exception:
                ok = False
                break
            preds.append(pr)
            trues.append(acc[te])
        if not ok or not preds:
            results[form] = dict(cv_r2=float('nan'))
            continue
        preds = np.concatenate(preds)
        trues = np.concatenate(trues)
        ss = np.sum((trues - trues.mean()) ** 2)
        r2 = 1 - np.sum((trues - preds) ** 2) / ss if ss > 0 else float('nan')
        results[form] = dict(cv_r2=float(r2), n=int(len(trues)))
    return results


def _predict_form(form, ztr, acctr, zte):
    if form == 'F_exp':
        A = np.vstack([np.ones_like(ztr), -ztr]).T
        coef, *_ = np.linalg.lstsq(A, np.log(acctr), rcond=None)
        return np.exp(coef[0] - coef[1] * zte)
    if form == 'F_pow':
        A = np.vstack([np.ones_like(ztr), -np.log(ztr)]).T
        coef, *_ = np.linalg.lstsq(A, np.log(acctr), rcond=None)
        return np.exp(coef[0]) * zte ** (-coef[1])
    if form == 'F_log':
        from scipy.optimize import curve_fit
        def f(x, k, z0):
            return 1.0 / (1.0 + np.exp(np.clip(k * (x - z0), -40, 40)))
        p, _ = curve_fit(f, ztr, acctr, p0=[1.0, np.median(ztr)], maxfev=20000)
        return f(zte, *p)
    if form == 'F_hyp':
        from scipy.optimize import curve_fit
        def f(x, a, k):
            return a / (1.0 + k * x)
        p, _ = curve_fit(f, ztr, acctr, p0=[1.0, 1.0], maxfev=20000)
        return f(zte, *p)
    raise ValueError(form)


# ----------------------------------------------------------------------------
# experiment driver
# ----------------------------------------------------------------------------

def build_families(sweep_n=15, n_chain_max=24):
    fams = []

    # --- ODE families ------------------------------------------------------
    for rho in np.linspace(20.0, 48.0, sweep_n):
        f, J = _make_lorenz(rho=float(rho))
        fam = Family('lorenz', 'flow', 3, None, J, 0.01, dict(rho=float(rho)))
        fam._rhs = f
        fams.append(fam)
    for c in np.linspace(3.5, 8.5, sweep_n):
        f, J = _make_rossler(c=float(c))
        fam = Family('rossler', 'flow', 3, None, J, 0.05, dict(c=float(c)))
        fam._rhs = f
        fams.append(fam)

    # --- 1D map ------------------------------------------------------------
    for r in np.linspace(3.55, 3.999, sweep_n):
        step, jac = _logistic_step(float(r))
        fams.append(Family('logistic', 'map', 1, step, jac, 1.0,
                           dict(r=float(r))))

    # --- constant-padded flows (d inert) ----------------------------------
    for m in np.linspace(0, 13, sweep_n).astype(int):
        f, J = _make_lorenz()
        fam = Family('lorenz_pad', 'flow', 3 + int(m), None, J, 0.01,
                     dict(pad=int(m)))
        fam._rhs = f
        fam.pad = int(m)
        fams.append(fam)
    for m in np.linspace(0, 13, sweep_n).astype(int):
        f, J = _make_rossler()
        fam = Family('rossler_pad', 'flow', 3 + int(m), None, J, 0.05,
                     dict(pad=int(m)))
        fam._rhs = f
        fam.pad = int(m)
        fams.append(fam)

    # --- 2D maps -----------------------------------------------------------
    for u in np.linspace(0.0, 1.0, sweep_n):
        step, jac = _hubble_step(float(u))
        fams.append(Family('hubble', 'map', 2, step, jac, 1.0, dict(u=float(u))))
    for a in np.linspace(0.8, 1.4, sweep_n):
        step, jac = _henon_step(a=float(a))
        fams.append(Family('henon', 'map', 2, step, jac, 1.0, dict(a=float(a))))
    for c in np.linspace(0.0, 0.6, sweep_n):
        step, jac = _coupled_logistic_step(3.8, float(c))
        fams.append(Family('coupled_logistic', 'map', 2, step, jac, 1.0,
                           dict(c=float(c))))

    # --- genuinely-active chain (d real) ----------------------------------
    ns = np.unique(np.linspace(1, n_chain_max, sweep_n).astype(int))
    for n in ns:
        step, jac = _chain_logistic_step(3.9, 0.2, int(n))
        fams.append(Family('chain_logistic', 'map', int(n), step, jac, 1.0,
                           dict(n=int(n)), active=int(n)))
    return fams


def run_one(fam, seed=0):
    rng = np.random.default_rng(seed)
    x0 = rng.uniform(0.1, 0.9, fam.d)

    if 'pad' in fam.params:
        # padded copies: evolve active coords, hold the rest constant
        m = fam.pad
        base = Family(fam.name, fam.kind, fam.d - m, None, None, fam.dt, {})
        base._rhs = fam._rhs
        base.jac = fam.jac
        x0b = x0[:fam.d - m]
        traj_b = base.integrate(x0b, 4000, 9000)
        lam = base.lyapunov(x0b, 4000, 4000)
        pad_vals = x0[fam.d - m:]
        traj = np.hstack([traj_b, np.tile(pad_vals, (len(traj_b), 1))])
        d = fam.d
    else:
        traj = fam.integrate(x0, 4000, 9000)
        lam = fam.lyapunov(x0, 4000, 4000)
        d = fam.d

    # measurement series: first ACTIVE coordinate (constants carry no signal)
    ts = traj[:, 0].astype(float)
    if np.std(ts) < 1e-9:
        return None

    d2 = correlation_dimension(ts, m=5, tau=None)
    lag, ac_target = decorrelation_lag(ts, 0.5, maxlag=min(600, len(ts) // 6))
    acc = prediction_accuracy(ts, lag)

    flags = []
    if not np.isfinite(lam) or lam <= 0.02:
        flags.append('not_chaotic')
    if not np.isfinite(d2) or d2 < 0.25:
        flags.append('no_scaling')
    if not np.isfinite(acc) or acc <= 0.01:
        flags.append('acc_floor')
    if np.isfinite(acc) and acc >= 0.999:
        flags.append('acc_ceiling')

    return dict(family=fam.name, params=fam.params, d=int(d),
                active=int(fam.active), kind=fam.kind, dt=fam.dt,
                lam=float(lam), D2=float(d2), lag=int(lag),
                acc=float(acc), z=float(lam * d2 * d),
                z_nod=float(lam * d2), flags=flags)


def main():
    sweep_n = int(os.environ.get('SWEEP_N', '15'))
    fams = build_families(sweep_n=sweep_n)
    print(f"total systems: {len(fams)}", flush=True)

    rows, dropped = [], []
    for i, fam in enumerate(fams):
        try:
            r = run_one(fam, seed=i)
        except Exception as e:
            r = None
            dropped.append(dict(family=fam.name, params=fam.params,
                                error=repr(e)))
        if r is None:
            dropped.append(dict(family=fam.name, params=fam.params,
                                error='degenerate'))
            continue
        if r['flags']:
            dropped.append(dict(family=fam.name, params=fam.params,
                                flags=r['flags'], acc=r['acc'],
                                lam=r['lam'], D2=r['D2']))
        else:
            rows.append(r)
        if (i + 1) % 25 == 0:
            print(f"  {i+1}/{len(fams)} done; kept={len(rows)}", flush=True)

    print(f"\nkept = {len(rows)}, dropped = {len(dropped)}", flush=True)
