    """R^2 of best linear (persistence-like) h-step predictor, for h=1..hmax."""
    ts=np.asarray(ts,float); out=np.full(hmax,np.nan)
    var=np.sum((ts-ts.mean())**2)
    for h in range(1,hmax+1):
        x=ts[:-h]; y=ts[h:]
        A=np.column_stack([np.ones_like(x),x])
        c,*_=np.linalg.lstsq(A,y,rcond=None)
        res=np.sum((y-A@c)**2)
        out[h-1]=1-res/var if var>0 else np.nan
