    hmax=min(300,len(ts)//8)
    curve=acc_curve(ts,hmax)
    H={f'H{q}':echo_horizon(curve,q) for q in (0.9,0.75,0.5,0.25)}
    return dict(fam=sysobj.fam,name=sysobj.name,d=int(d),active=int(sysobj.active),
                pad=m,kind=sysobj.kind,lam=float(lam),D2=float(D2),tau=int(tau),
                hmax=int(hmax),curve=[float(v) for v in curve],**H)

# ---------------- modes ---------------------------------------------------
def mode_main():
