transcription risk between sandbox and World C. Previous attempt failed only on
a relative-path assumption (documented '../../instances/...' resolves one level
short from the actual job CWD). This version walks up the directory tree until
it finds the staged file.
"""
import runpy, os, sys, traceback

SCRIPT_NAME = 'eh14_window_audit.py'

def find_staged(start=None, max_up=6):
    start = os.path.abspath(start or os.getcwd())
    rel_candidates = [
        os.path.join('instances', 'shared_space', 'world_c', 'artifacts', SCRIPT_NAME),
        os.path.join('shared_space', 'world_c', 'artifacts', SCRIPT_NAME),
    ]
    cur = start
    for _ in range(max_up):
        for rel in rel_candidates:
            p = os.path.join(cur, rel)
            if os.path.exists(p):
                return p
        parent = os.path.dirname(cur)
        if parent == cur:
            break
        cur = parent
    # last resort: shallow glob from cwd
    for root, dirs, files in os.walk(start):
        if root.count(os.sep) - start.count(os.sep) > 4:
            dirs[:] = []
        if SCRIPT_NAME in files and 'shared_space' in root and 'artifacts' in root:
            return os.path.join(root, SCRIPT_NAME)
    return None

SRC = find_staged()
print('cwd =', os.getcwd(), flush=True)
print('staged script ->', SRC, flush=True)
assert SRC, 'staged eh14_window_audit.py not found anywhere above job CWD'

try:
    runpy.run_path(SRC, run_name='__main__')
except Exception:
